import sqlite3
from dataclasses import dataclass, asdict
from datetime import datetime, timedelta

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("clinic-appointments")

SMS_GATEWAY_URL = "https://sms.clinic.example.com/v1/messages"
DB_PATH = "clinic.db"


@dataclass
class RescheduleResult:
    appointment_id: int
    moved: bool
    old_start: str = ""
    new_start: str = ""
    notice_sent: bool = False
    message: str = ""


@mcp.tool()
def reschedule_appointment_with_notice(appointment_id: int, new_start_time: str) -> dict:
    try:
        new_start = datetime.fromisoformat(new_start_time)
    except ValueError:
        return asdict(RescheduleResult(appointment_id, False, message="Invalid time format"))

    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT a.starts_at, a.duration_minutes, a.provider_id, p.phone "
            "FROM appointments a JOIN patients p ON p.id = a.patient_id WHERE a.id = ?",
            (appointment_id,),
        ).fetchone()
        if row is None:
            return asdict(RescheduleResult(appointment_id, False, message="Appointment not found"))
        old_start, duration, provider_id, phone = row
        new_end = new_start + timedelta(minutes=duration)
        conflict = conn.execute(
            "SELECT 1 FROM appointments WHERE provider_id = ? AND id != ? "
            "AND starts_at < ? AND ends_at > ?",
            (provider_id, appointment_id, new_end.isoformat(), new_start.isoformat()),
        ).fetchone()
        if conflict:
            return asdict(RescheduleResult(appointment_id, False, old_start, message="Slot is already booked"))
        conn.execute(
            "UPDATE appointments SET starts_at = ?, ends_at = ? WHERE id = ?",
            (new_start.isoformat(), new_end.isoformat(), appointment_id),
        )
        conn.commit()
    finally:
        conn.close()

    sent = False
    try:
        resp = requests.post(
            SMS_GATEWAY_URL,
            json={
                "to": phone,
                "body": f"Your appointment has been moved to {new_start.strftime('%b %d at %I:%M %p')}.",
            },
            timeout=10,
        )
        sent = resp.ok
    except requests.RequestException:
        sent = False

    return asdict(
        RescheduleResult(
            appointment_id,
            True,
            old_start,
            new_start.isoformat(),
            sent,
            "Rescheduled" if sent else "Rescheduled but text failed to send",
        )
    )
